insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 22, 'Então Aimaás filho de Zadoque voltou a dizer a Joabe: Seja o que for, eu correrei agora atrás do cuxita. E Joabe disse: Filho meu, para que hás tu de escorrer, pois que não acharás prêmio pelas novas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 23, 'Mas ele respondeu: Seja o que for, eu correrei. Então lhe disse: Corre. Correu, pois, Aimaás pelo caminho da planície, e passou diante do cuxita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 24, 'Estava Davi naquele tempo sentado entre as duas portas; e o atalaia havia ido ao terraço de sobre a porta no muro, e levantando seus olhos, olhou, e viu a um que corria sozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 25, 'O vigilante deu logo vozes, e o fez saber ao rei. E o rei disse: Se está sozinho, boas novas traze. Em tanto que ele vinha aproximando-se,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 26, 'Viu o vigilante outro que corria; e deu vozes o vigilante ao porteiro, dizendo: Eis que outro homem que corre sozinho. E o rei disse: Este também é mensageiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 27, 'E o vigilante voltou a dizer: Parece-me o correr do primeiro como o correr de Aimaás filho de Zadoque. E respondeu o rei: Esse é homem de bem, e vem com boa nova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 28, 'Então Aimaás disse em alta voz ao rei: Paz. E inclinou-se à terra diante do rei, e disse: Bendito seja o SENHOR Deus teu, que entregou aos homens que haviam levantado suas mãos contra meu senhor o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 29, 'E o rei disse: O jovem Absalão tem paz? E Aimaás respondeu: Vi eu um grande alvoroço quando enviou Joabe ao servo do rei e a mim teu servo; mas não sei que era.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 30, 'E o rei disse: Passa, e põe-te ali. E ele passou, e parou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 31, 'E logo veio o cuxita, e disse: Receba notícia, meu senhor o rei, que hoje o SENHOR defendeu tua causa da mão de todos os que se haviam levantado contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 32, 'O rei então disse ao cuxita: O jovem Absalão tem paz? E o cuxita respondeu: Sejam como aquele jovem os inimigos de meu senhor o rei, e todos os que se levantam contra ti para mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 18, 33, 'Então o rei se perturbou, e subiu-se à sala da porta, e chorou; e indo, dizia assim: Filho meu Absalão, filho meu, filho meu Absalão! Quem me dera que morresse eu em lugar de ti, Absalão, filho meu, filho meu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 1, 'E deram aviso a Joabe: Eis que o rei chora, e faz luto por Absalão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 2, 'E voltou-se aquele dia a vitória em luto para todo aquele povo; porque ouviu dizer o povo aquele dia que o rei tinha dor por seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 3, 'Entrou-se o povo aquele dia na cidade escondidamente, como costuma entrar às escondidas o povo envergonhado que fugiu da batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 4, 'Mas o rei, coberto o rosto, clamava em alta voz: Filho meu Absalão, Absalão, filho meu, filho meu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 5, 'E entrando Joabe em casa ao rei, disse-lhe: Hoje envergonhaste o rosto de todos os teus servos, que hoje livraram tua vida, e a vida de teus filhos e de tuas filhas, e a vida de tuas mulheres, e a vida de tuas concubinas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 6, 'Amando aos que te aborrecem, e aborrecendo aos que te amam: porque hoje declaraste que nada te importam teus príncipes e servos; pois hoje deste a entender que se Absalão vivesse, bem que nós todos estivéssemos hoje mortos, então te contentarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 7, 'Levanta-te, pois, agora, e sai fora, e elogia a teus servos: porque juro pelo SENHOR, que se não saíres, nem um sequer ficará contigo esta noite; e disto te pesará mais que de todos os males que te sobrevieram desde tua juventude até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 8, 'Então se levantou o rei, e sentou-se à porta; e foi declarado a todo aquele povo, dizendo: Eis que o rei está sentado à porta. E veio todo aquele povo diante do rei; mas Israel havia fugido, cada um a suas moradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 9, 'E todo aquele povo discutia em todas as tribos de Israel, dizendo: O rei nos livrou da mão de nossos inimigos, e ele nos salvou da mão dos filisteus; e agora havia fugido, da terra por medo de Absalão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 10, 'E Absalão, a quem havíamos ungido sobre nós, é morto na batalha. Por que, pois, estais agora quietos em ordem a fazer voltar ao rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 11, 'E el rei Davi enviou a Zadoque e a Abiatar sacerdotes, dizendo: Falai aos anciãos de Judá e dizei-lhes: Por que sereis vós os últimos em voltar o rei à sua casa, já que a palavra de todo Israel veio ao rei de voltar-lhe à sua casa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 12, 'Vós sois meus irmãos; sois meus ossos e minha carne; por que, pois sereis vós os últimos em voltar ao rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 13, 'Também direis a Amasa: Não és tu também osso meu e carne minha? Assim me faça Deus, e assim me acrescente, se não fores general do exército diante de mim para sempre, em lugar de Joabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 14, 'Assim inclinou o coração de todos os homens de Judá, como o de um só homem, para que enviassem a dizer ao rei: Volta, com todos os teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 15, 'Voltou, pois o rei, e veio até o Jordão. E Judá veio a Gilgal, a receber ao rei e fazê-lo passar o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 16, 'E Simei filho de Gera, filho de Benjamim, que era de Baurim, apressou-se a vir com os homens de Judá a receber ao rei Davi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 17, 'E com ele vinham mil homens de Benjamim; também Ziba criado da casa de Saul, com seus quinze filhos e seus vinte servos, os quais passaram o Jordão diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 18, 'Atravessou depois o barco para passar a família do rei, e para fazer o que lhe agradasse. Então Simei filho de Gera se prostrou diante do rei quando ele havia passado o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 19, 'E disse ao rei: Não me impute meu senhor iniquidade, nem tenhas memória dos males que teu servo fez o dia que meu senhor o rei saiu de Jerusalém, para guardá-los o rei em seu coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 20, 'Porque eu teu servo conheço haver pecado, e vim hoje o primeiro de toda a casa de José, para descer a receber a meu senhor o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 21, 'E Abisai filho de Zeruia respondeu e disse: Não morrerá por isto Simei, que amaldiçoou ao ungido do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 22, 'Davi então disse: Que tendes vós comigo, filhos de Zeruia, que me haveis de ser hoje adversários? Morrerá hoje alguém em Israel? Não sei eu que hoje sou rei sobre Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 23, 'E disse o rei a Simei: Não morrerás. E o rei jurou a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 24, 'Também Mefibosete filho de Saul desceu a receber ao rei: não havia lavado seus pés, nem havia cortado sua barba, nem tampouco havia lavado suas roupas, desde o dia que o rei saiu até o dia que veio em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 25, 'E logo que veio ele a Jerusalém a receber ao rei, o rei lhe disse: Mefibosete, Por que não foste comigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 26, 'E ele disse: Rei senhor meu, meu servo me enganou; pois havia teu servo dito: Prepararei um asno, e subirei nele, e irei ao rei; porque teu servo é coxo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 27, 'Porém ele caluniou a teu servo diante de meu senhor o rei; mas meu senhor o rei é como um anjo de Deus: faze, pois, o que bem te parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 28, 'Porque toda a casa de meu pai era digna de morte diante de meu senhor o rei, e tu puseste a teu servo entre os convidados de tua mesa. Que direito, pois, tenho ainda para queixar-me mais contra o rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 29, 'E o rei lhe disse: Para que falas mais palavras? Eu determinei que tu e Ziba repartais as terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 30, 'E Mefibosete disse ao rei: E ainda tome-as ele todas, pois que meu senhor o rei voltou em paz à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 31, 'Também Barzilai gileadita desceu de Rogelim, e passou o Jordão com o rei, para acompanhar-lhe da outra parte do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 32, 'E era Barzilai muito velho, de oitenta anos, o qual havia dado provisão ao rei quando estava em Maanaim, porque era homem muito rico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 33, 'E o rei disse a Barzilai: Passa comigo, e eu te darei de comer comigo em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 34, 'Mas Barzilai disse ao rei: Quantos são os dias do tempo de minha vida, para que eu suba com o rei a Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 35, 'Eu sou hoje da idade de oitenta anos, que já não farei diferença entre o bem e o mal: tomará gosto agora teu servo no que comer ou beber? Ouvirei mais a voz dos cantores e das cantoras? Para que, pois, seria ainda teu servo incômodo ao meu senhor, o rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 36, 'Passará teu servo um pouco o Jordão com o rei: por que me há de dar o rei tão grande recompensa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 37, 'Eu te rogo que deixes voltar a teu servo, e que morra em minha cidade, junto ao sepulcro de meu pai e de minha mãe. Eis aqui teu servo Quimã; que passe ele com meu senhor o rei, e faze-lhe o que bem te parecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 38, 'E o rei disse: Pois passe comigo Quimã, e eu farei com ele como bem te pareça: e tudo o que tu me pedires, eu o farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 39, 'E todo aquele povo passou o Jordão: e logo que o rei também passou, o rei beijou a Barzilai, e abençoou-o; e ele se voltou à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 40, 'O rei então passou a Gilgal, e com ele passou Quimã; e todo aquele povo de Judá, com a metade do povo de Israel, acompanharam o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 41, 'E eis que todos os homens de Israel vieram ao rei, e lhe disseram: Por que os homens de Judá, nossos irmãos, te levaram, e fizeram passar o Jordão ao rei e à sua família, e a todos os homens de Davi com ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 42, 'E todos os homens de Judá responderam a todos os de Israel: Porque o rei é nosso parente. Mas por que vos irais vós disso? Temos nós comido algo do rei? Temos recebido dele algum presente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 19, 43, 'Então responderam os homens de Israel, e disseram aos de Judá: Nós temos no rei dez partes, e no mesmo Davi mais que vós: por que, pois, nos haveis tido em pouco? Não falamos nós primeiro em voltar a nosso rei? E o argumento dos homens de Judá prevaleceu ao dos homens de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 1, 'E aconteceu estar ali um homem perverso que se chamava Seba, filho de Bicri, homem de Benjamim, o qual tocou a trombeta, e disse: Não temos nós parte em Davi, nem herança no filho de Jessé: Israel, cada um a suas moradas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 2, 'Assim deixaram de seguir Davi todos os homens de Israel, e seguiam a Seba filho de Bicri: mas os de Judá se aderiram a seu rei, desde o Jordão até Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 3, 'E logo que chegou Davi a sua casa em Jerusalém, tomou o rei as dez mulheres concubinas que havia deixado para guardar a casa, e as pôs em uma casa em guarda, e deu-lhes de comer: mas nunca mais entrou a elas, mas sim que ficaram encerradas até que morressem como viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 4, 'Depois o rei disse a Amasa: Convoca-me os homens de Judá para dentro de três dias, e apresenta-te aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 5, 'Foi, pois, Amasa, convocar Judá; mas demorou-se além do tempo que lhe havia sido designado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 6, 'E disse Davi a Abisai: Seba, filho de Bicri, nos fará agora mais mal que Absalão; toma, pois, tu, os servos do teu senhor, e vai atrás dele, para que ele não ache as cidades fortificadas, e escape de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 7, 'Então saíram depois dele os homens de Joabe, e os quereteus e peleteus, e todos os valentes: saíram de Jerusalém para ir atrás de Seba filho de Bicri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 8, 'E estando eles próximo da grande penha que está em Gibeão, saiu-lhes Amasa ao encontro. Agora bem, a vestimenta que Joabe tinha sobreposta estava-lhe cingida, e sobre ela o cinto de um punhal apegado a seus lombos em sua bainha, da que assim quando ele avançou, o punhal caiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 9, 'Então Joabe disse a Amasa: Tens paz, irmão meu? E tomou Joabe com a direita a barba de Amasa, para beijá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 10, 'E como Amasa não se cuidou do punhal que Joabe na mão tinha, feriu-lhe este com ela na quinta costela, e derramou suas entranhas por terra, e caiu morto sem dar-lhe segundo golpe. Depois Joabe e seu irmão Abisai perseguiram Seba filho de Bicri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 11, 'E um dos criados de Joabe se parou junto a ele, dizendo: Qualquer um que amar a Joabe e a Davi vá atrás de Joabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 12, 'E Amasa se havia revolvido no sangue no meio do caminho: e vendo aquele homem que todo aquele povo se parava, separou a Amasa do caminho ao campo, e lançou sobre ele uma vestimenta, porque via que todos os que vinham se paravam junto a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 13, 'Logo, pois, que foi afastado do caminho, passaram todos os que seguiam a Joabe, para ir atrás de Seba filho de Bicri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 14, 'E ele passou por todas as tribos de Israel até Abel e Bete-Maaca e toda a terra dos beritas: e juntaram-se, e seguiram-no também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 15, 'E vieram e cercaram-no em Abel de Bete-Maaca, e puseram baluarte contra a cidade; e posto que foi ao muro, todo aquele povo que estava com Joabe trabalhava por derrubar a muralha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 16, 'Então uma mulher sábia deu vozes na cidade, dizendo: Ouvi, ouvi; rogo-vos que digais a Joabe se chegue a aqui, para que eu fale com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 17, 'E quando ele se aproximou a ela, disse a mulher: És tu Joabe? E ele respondeu: Eu sou. E ela lhe disse: Ouve as palavras de tua serva. E ele respondeu: Ouço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 18, 'Então voltou ela a falar, dizendo: Antigamente costumavam falar, dizendo: Quem perguntar, pergunte em Abel: e assim concluíam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 19, 'Eu sou das pacíficas e fiéis de Israel: e tu procuras destruir uma cidade que é mãe de Israel: por que destróis a herança do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 20, 'E Joabe respondeu, dizendo: Nunca tal, nunca tal me aconteça, que eu destrua nem desfaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 21, 'A coisa não é assim: mas um homem do monte de Efraim, que se chama Seba filho de Bicri, levantou sua mão contra o rei Davi: entregai a esse somente, e me irei da cidade. E a mulher disse a Joabe: Eis que sua cabeça te será lançada desde o muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 22, 'A mulher foi logo a todo aquele povo com sua sabedoria; e eles cortaram a cabeça a Seba filho de Bicri, e lançaram-na a Joabe. E ele tocou a trombeta, e dispersaram-se da cidade, cada um à sua morada. E Joabe se voltou ao rei a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 23, 'Assim ficou Joabe sobre todo aquele exército de Israel; e Benaia filho de Joiada sobre os quereteus e peleteus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 24, 'E Adorão sobre os tributos; e Josafá filho de Ailude, o cronista;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 25, 'E Seva, escriba; e Zadoque e Abiatar, sacerdotes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 20, 26, 'E Ira jairita foi um chefe oficial de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 1, 'E nos dias de Davi houve fome por três anos consecutivos. E Davi consultou ao SENHOR, e o SENHOR lhe disse: É por Saul, e por aquela casa de sangue; porque matou aos gibeonitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 2, 'Então o rei chamou aos gibeonitas, e falou-lhes. (Os gibeonitas não eram dos filhos de Israel, mas sim do resto dos amorreus, aos quais os filhos de Israel fizeram juramento; mas Saul havia procurado matá-los com motivo de zelo pelos filhos de Israel e de Judá).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 3, 'Disse, pois Davi aos gibeonitas: Que vos farei, e com que expiarei para que abençoeis à herança do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 4, 'E os gibeonitas lhe responderam: Não temos nós queixa sobre prata nem sobre ouro com Saul, e com sua casa: nem queremos que morra homem de Israel. E ele lhes disse: O que vós disserdes vos farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 5, 'E eles responderam ao rei: Daquele homem que nos destruiu, e que tramou contra nós, para nos exterminar sem deixar nada de nós em todo aquele termo de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 6, 'Deem-se a nós sete homens de seus filhos, para que os enforquemos ao SENHOR em Gibeá de Saul, o escolhido do SENHOR. E o rei disse: Eu os darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 7, 'E perdoou o rei a Mefibosete, filho de Jônatas, filho de Saul, pelo juramento do SENHOR que havia entre eles, entre Davi e Jônatas filho de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 8, 'Mas tomou o rei dois filhos de Rispa filha de Aiá, os quais ela havia dado à luz de Saul, a saber, a Armoni e a Mefibosete; e cinco filhos de Mical filha de Saul, os quais ela havia dado à luz de Adriel, filho de Barzilai meolatita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 9, 'E entregou-os em mãos dos gibeonitas, e eles os enforcaram no monte diante do SENHOR: e morreram juntos aqueles sete, os quais foram mortos no tempo da colheita, nos primeiros dias, no princípio da colheita das cevadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 10, 'Tomando logo Rispa filha de Aiá um saco, estendeu-o sobre um penhasco, desde o princípio da colheita até que choveu sobre eles água do céu; e não deixou a nenhuma ave do céu assentar-se sobre eles de dia, nem animais do campo de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 11, 'E foi dito a Davi o que fazia Rispa filha de Aiá, concubina de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 12, 'Então Davi foi, e tomou os ossos de Saul e os ossos de Jônatas seu filho, dos homens de Jabes de Gileade, que os haviam furtado da praça de Bete-Seã, de onde os haviam pendurado os filisteus, quando os filisteus mataram a Saul em Gilboa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 13, 'E fez levar dali os ossos de Saul e os ossos de Jônatas seu filho; e juntaram também os ossos dos enforcados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 14, 'E sepultaram os ossos de Saul e os de seu filho Jônatas em terra de Benjamim, em Selá, no sepulcro de Quis seu pai; e fizeram tudo o que o rei havia mandado. Depois se aplacou Deus com a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 15, 'Quando os filisteus voltaram a fazer guerra a Israel, Davi desceu com os seus servos, e lutaram contra os filisteus; e Davi se cansou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 16, 'Nisso, Isbi-Benobe, que era dos filhos do gigante, e que cuja lança pesava trezentos siclos de bronze, estando ele cingido com uma espada nova, pretendeu ferir Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 17, 'Mas Abisai, filho de Zeruia, o socorreu, feriu o filisteu, e o matou. Então os homens de Davi lhe juraram, dizendo: “Nunca mais sairás conosco à batalha, para que não apagues a lâmpada de Israel.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 18, 'Outra segunda guerra houve depois em Gobe contra os filisteus; então Sibecai, husatita, feriu a Safe, que era dos filhos do gigante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 19, 'Outra guerra houve em Gobe contra os filisteus, na qual Elanã, filho de Jaaré-Oregim de Belém, feriu a Golias geteu, a haste de cuja lança era como um lançador de tear.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 20, 'Depois houve outra guerra em Gate, de onde houve um homem de grande altura, o qual tinha doze dedos nas mãos, e outros doze nos pés, vinte e quatro em todos: e também era dos filhos do gigante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 21, 'Este desafiou a Israel, e foi morto por Jônatas, filho de Simeia irmão de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 21, 22, 'Estes quatro lhe haviam nascido ao gigante em Gate, os quais caíram pela mão de Davi e pela mão de seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 1, 'E falou Davi ao SENHOR as palavras deste cântico, o dia que o SENHOR o livrou da mão de todos os seus inimigos e da mão de Saul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 2, 'E disse: O SENHOR é minha rocha, e minha fortaleza, e meu libertador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 3, 'Deus de minha rocha, nele confiarei: Meu escudo, e o poder de minha salvação, minha fortaleza, e meu refúgio; Meu salvador, que me livrarás de violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 4, 'Invocarei ao SENHOR, digno de ser louvado. E serei salvo de meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 5, 'Quando me cercaram ondas de morte, E ribeiros de iniquidade me assombraram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 6, 'As cordas do Xeol me rodearam, e laços de morte me tomaram desprevenido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 7, 'Tive angústia, invoquei ao SENHOR, E clamei a meu Deus: E ele ouviu minha voz desde seu templo; Chegou meu clamor a seus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 8, 'A terra se moveu, e tremeu; Os fundamentos dos céus foram movidos, E se estremeceram, porque ele se irou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 9, 'Subiu fumaça de suas narinas, E de sua boca fogo consumidor, Pelo qual se acenderam carvões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 10, 'E abaixo os céus, e desceu: Uma escuridão debaixo de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 11, 'Subiu sobre o querubim, e voou: Apareceu-se sobre as asas do vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 12, 'Armou tendas de escuridão ao redor de si; nuvens negras e espessas, carregadas de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 13, 'Do resplendor de sua presença Se acenderam brasas ardentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 14, 'O SENHOR trovejou desde os céus, E o Altíssimo deu sua voz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 15, 'Lançou flechas, e desbaratou-os; Relampejou, e consumiu-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 16, 'Então apareceram as profundezas do mar, E os fundamentos do mundo foram descobertos, À repreensão do SENHOR, Ao sopro do vento de seu nariz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 17, 'Estendeu sua mão do alto, e arrebatou-me, E tirou-me de copiosas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 18, 'Livrou-me de fortes inimigos, De aqueles que me aborreciam, os quais eram mais fortes que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 19, 'Atacaram-me no dia de minha calamidade; Mas o SENHOR foi meu apoio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 20, 'Tirou-me para um lugar amplo; Livrou-me, porque se agradou de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 21, 'Remunerou-me o SENHOR conforme minha justiça: E conforme a limpeza de minhas mãos ele me pagou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 22, 'Porque eu guardei os caminhos do SENHOR; E não me apartei impiamente de meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 23, 'Porque diante de mim tenho todas suas ordenanças; E atento a seus estatutos, não me retirarei deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 24, 'E fui íntegro para com ele, E guardei-me de minha iniquidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 25, 'Remunerou-me, portanto, o SENHOR conforme minha justiça, E conforme minha limpeza diante de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 26, 'Com o bom és benigno, E com o íntegro te mostras íntegro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 27, 'Limpo és para com o limpo, Mas com o perverso és rígido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 28, 'E tu salvas ao povo humilde; Mas teus olhos sobre os altivos, para abatê-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 29, 'Porque tu és minha lâmpada, ó SENHOR; o SENHOR dá luz às minhas trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 30, 'Pois contigo avançarei contra uma tropa, e com o meu Deus saltarei uma muralha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 31, 'O caminho de Deus [é] perfeito; a palavra do SENHOR [é] purificada, é escudo é de todos os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 32, 'Porque que Deus há a não ser o SENHOR? Ou quem é forte a não ser nosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 33, 'Deus é o que com virtude me corrobora, e o que tira os obstáculos do meu caminho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 34, 'O que faz meus pés como de cervas, E o que me assenta em minhas alturas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 35, 'O que ensina minhas mãos para a luta, e proporciona que com meus braços quebre o arco de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 36, 'Tu me deste também o escudo de tua salvação, E tua benignidade me acrescentou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 37, 'Tu alargaste meus desfiladeiros debaixo de mim, Para que não titubeassem meus joelhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 38, 'Perseguirei a meus inimigos, e os quebrantarei; E não me voltarei até que os acabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 39, 'Os consumirei, e os ferirei, e não se levantarão; E cairão debaixo de meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 40, 'Cingiste-me de força para a batalha, E fizeste prostrar debaixo de mim os que contra mim se levantaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 41, 'Tu me deste o pescoço de meus inimigos, De meus aborrecedores, que eu os destruísse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 42, 'Olharam, e não houve quem os livrasse; Ao SENHOR, mas não lhes respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 43, 'Eu os esmiuçarei como pó da terra; Eu os pisarei como à lama das ruas, e os dissiparei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 44, 'Tu me livraste das brigas dos povos; Tu me guardaste para eu que fosse cabeça de nações: Povos que eu não conhecia me serviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 45, 'Os estrangeiros se sujeitaram a mim; ao ouvirem, me obedeciam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 46, 'Os estrangeiros desfaleciam, E tremiam em seus esconderijos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 47, 'Viva o SENHOR, e seja bendita minha rocha; Seja exaltado o Deus, a rocha de meu salvamento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 48, 'O Deus que me vingou, E sujeita os povos debaixo de mim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 49, 'E que me tira dentre meus inimigos: Tu me tiraste em alto dentre os que se levantaram contra mim: Livraste-me do homem de iniquidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 50, 'Portanto eu te confessarei entre as nações, ó SENHOR, E cantarei a teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 22, 51, 'Ele que engrandece as saúdes de seu rei, E faz misericórdia a seu ungido, A Davi, e à sua semente, para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 1, 'Estas são as últimas palavras de Davi. Disse Davi filho de Jessé, Disse aquele homem que foi levantado alto, O ungido do Deus de Jacó, O suave em cânticos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 2, 'O espírito do SENHOR falou por mim, E sua palavra foi em minha língua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 3, 'O Deus de Israel disse, Falou-me o Forte de Israel: O dominador dos homens será justo. Dominador em temor de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 4, 'Será como a luz da manhã quando sai o sol, Da manhã sem nuvens; Quando a erva da terra brota Por meio do resplendor depois da chuva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 5, 'Não está minha casa com Deus? Pois ele fez comigo um pacto perpétuo, Ordenado em todas as coisas, e será guardado; pois não é dele que brotará toda a minha salvação e todo o meu desejo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 6, 'Mas os malignos serão todos eles como espinhos arrancados, os quais ninguém toma com a mão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 7, 'Em vez disso o que quer tocar neles, Arma-se de ferro e de haste de lança, e são queimados em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 8, 'Estes são os nomes dos valentes que teve Davi: Josebe-Bassebete, o taquemonita, principal dos capitães: era este Adino o eznita, que matou em uma ocasião sobre oitocentos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 9, 'Depois deste, Eleazar, filho de Dodô de Aoí, foi dos três valentes que estavam com Davi, quando desafiaram aos filisteus que se haviam juntado ali à batalha, e subiram os de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 10, 'Este, levantando-se, feriu aos filisteus, até que sua mão se cansou, e ficou grudada em sua espada. Aquele dia o SENHOR fez grande salvação; e voltou-se o povo depois dele somente para tomar o despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 11, 'Depois deste foi Samá, filho de Agé araíta: que havendo os filisteus se juntado em uma aldeia, havia ali um terreno cheio de lentilhas, e o povo havia fugido diante dos filisteus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 12, 'Ele então se parou em meio do terreno e defendeu-o, e feriu aos filisteus; e o SENHOR fez uma grande salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 13, 'E três dos trinta principais desceram e vieram em tempo da colheita a Davi à cova de Adulão: e o acampamento dos filisteus estava no vale de Refaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 14, 'Davi então estava na fortaleza, e a guarnição dos filisteus estava em Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 15, 'E Davi teve desejo, e disse: Quem me dera a beber da água da cisterna de Belém, que está à porta!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 16, 'Então os três valentes irromperam pelo acampamento dos filisteus, e tiraram água da cisterna de Belém, que estava à porta; e tomaram, e trouxeram-na a Davi: mas ele não a quis beber, mas derramou-a ao SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 17, 'Longe seja de mim, ó SENHOR, que eu faça isto. Eis de beber eu o sangue dos homens que foram com perigo de sua vida? E não quis bebê-la. Os três valentes fizeram isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 18, 'E Abisai irmão de Joabe, filho de Zeruia, foi o principal dos três; o qual levantou sua lança contra trezentos, que matou; e teve nome entre os três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 19, 'Ele era o mais preeminente dos três, e o primeiro deles; mas não chegou aos três primeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 20, 'Depois, Benaia filho de Joiada, filho de um homem esforçado, grande em feitos, de Cabzeel. Este feriu dois leões de Moabe: e ele mesmo desceu, e feriu um leão em meio de um fosso no tempo da neve:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 21, 'Também feriu ele a um egípcio, homem de grande estatura; e tinha o egípcio uma lança em sua mão; mas desceu a ele com um cajado, e arrebatou ao egípcio a lança da mão, e o matou com sua própria lança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 22, 'Isto fez Benaia filho de Joiada, e teve nome entre os três valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 23, 'Dos trinta foi o mais preeminente; mas não chegou aos três primeiros. E Davi o pôs em seu conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 24, 'Asael irmão de Joabe foi dos trinta; Elanã filho de Dodô de Belém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 25, 'Samá harodita, Elica harodita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 26, 'Heles paltita, Ira, filho de Iques, de Tecoa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 27, 'Abiezer de Anatote, Mebunai husatita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 28, 'Zalmom aoíta, Maarai de Netofate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 29, 'Helebe filho de Baaná de Netofate, Itai filho de Ribai de Gibeá dos filhos de Benjamim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 30, 'Benaia piratonita, Hidai do ribeiro de Gaás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 31, 'Abi-Albom de Arbate, Azmavete barumita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 32, 'Eleaba de Saalbom, Jônatas dos filhos de Jásen;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 33, 'Samá de Harar, Aião filho de Sarar de Harar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 34, 'Elifelete filho de Aasbai filho do maacatita; Eliã filho de Aitofel gilonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 35, 'Hezrai do Carmelo, Paarai arbita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 36, 'Igal filho de Natã de Zobá, Bani gadita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 37, 'Zeleque de Amom, Naarai de Beerote, escudeiro de Joabe filho de Zeruia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 38, 'Ira itrita, Garebe itrita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 23, 39, 'Urias, o heteu. Entre todos, trinta e sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 1, 'E voltou o furor do SENHOR a acender-se contra Israel, e incitou a Davi contra eles a que dissesse: Vai, conta a Israel e a Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 2, 'E disse o rei a Joabe, general do exército que tinha consigo: Rodeia todas as tribos de Israel, desde Dã até Berseba, e contai o povo, para que eu saiba o número da gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 3, 'E Joabe respondeu ao rei: Acrescente o SENHOR teu Deus ao povo cem vezes tanto quanto são, e que o veja meu senhor ao rei; mas para que quer isto meu senhor o rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 4, 'Porém a palavra do rei pôde mais que Joabe, e que os capitães do exército. Saiu, pois, Joabe, com os capitães do exército, de diante do rei, para contar o povo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 5, 'E passando o Jordão assentaram em Aroer, à direita da cidade que está em meio do ribeiro de Gade e junto a Jazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 6, 'Depois vieram a Gileade, e à terra baixa de Hodsi: e dali vieram a Dã-Jaã e ao redor de Sídon.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 7, 'E vieram logo à fortaleza de Tiro, e a todas as cidades dos heveus e dos cananeus; e saíram ao sul de Judá, a Berseba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 8, 'E depois que andaram toda a terra, voltaram a Jerusalém ao fim de nove meses e vinte dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 9, 'E Joabe deu a conta do número do povo ao rei; e foram os de Israel oitocentos mil homens fortes que tiravam espada; e dos de Judá quinhentos mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 10, 'E depois que Davi contou o povo, sentiu-se atormentado em seu coração; e disse Davi ao SENHOR: Eu pequei gravemente por haver feito isto; mas agora, ó SENHOR, rogo-te que tires o pecado de teu servo, porque eu agi muito loucamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 11, 'E pela manhã, quando Davi se levantou, veio a palavra do SENHOR a Gade profeta, vidente de Davi, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 12, 'Vai, e dize a Davi: Assim disse o SENHOR: Três coisas te ofereço: tu te escolherás uma delas, a qual eu faça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 13, 'Veio, pois, Gade a Davi, e notificou-lhe, e disse-lhe: Queres que te venham sete anos de fome em tua terra? Ou que fujas três meses diante de teus inimigos, e que eles te persigam? Ou que três dias haja pestilência em tua terra? Pensa agora, e olha o que responderei ao que me enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 14, 'Então Davi disse a Gade: Em grande angústia estou: rogo que caia na mão do SENHOR, porque suas misericórdias são muitas, e que não caia eu em mãos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 15, 'E enviou o SENHOR pestilência a Israel desde a manhã até o tempo assinalado: e morreram do povo, desde Dã até Berseba, setenta mil homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 16, 'E quando o anjo estendeu sua mão sobre Jerusalém para destruí-la, o SENHOR se arrependeu daquele mal, e disse ao anjo que destruía o povo: Basta agora; detém tua mão. Então o anjo do SENHOR estava junto à eira de Araúna, o jebuseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 17, 'E Davi disse ao SENHOR, quando viu ao anjo que feria ao povo: Eu pequei, eu fiz a maldade: que fizeram estas ovelhas? Rogo-te que tua mão se torne contra mim, e contra a casa de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 18, 'E Gade veio a Davi aquele dia, e disse-lhe: Sobe, e faze um altar ao SENHOR na era de Araúna jebuseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 19, 'E subiu Davi, conforme ao dito de Gade, que o SENHOR lhe havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 20, 'E olhando Araúna, viu ao rei e a seus servos que passavam a ele. Saindo então Araúna, inclinou-se diante do rei até terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 21, 'E Araúna disse: Por que vem meu senhor o rei a seu servo? E Davi respondeu: Para comprar de ti a eira, para edificar altar ao SENHOR, a fim de que a mortandade cesse do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 22, 'E Araúna disse a Davi: Tome e sacrifique meu senhor o rei o que bem lhe parecer; eis aqui bois para o holocausto; e trilhos e outros equipamentos de bois para lenha:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 23, 'Tudo isto, ó rei, Araúna dá ao rei. Logo disse Araúna ao rei: o SENHOR teu Deus se agrade de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 24, 'E o rei disse a Araúna: Não, mas por preço o comprarei de ti; porque não oferecerei ao SENHOR meu Deus holocaustos gastando nada. Então Davi comprou a eira e os bois por cinquenta siclos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 10, '2 Samuel', '2Sm', 24, 25, 'E ali Davi edificou um altar ao SENHOR, e sacrificou holocaustos e ofertas pacíficas; e o SENHOR se aplacou com a terra, e cessou a praga de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 1, 'Quando o rei Davi era velho, e de idade avançada, cobriam-lhe de roupas, mas não se aquecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 2, 'Disseram-lhe portanto seus servos: Busquem a meu senhor o rei uma moça virgem, para que esteja diante do rei, e o abrigue, e durma a seu lado, e aquecerá a meu senhor o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 3, 'E buscaram uma moça formosa por todo o termo de Israel, e acharam a Abisague sunamita, e trouxeram-na ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 4, 'E a moça era formosa, a qual aquecia ao rei, e lhe servia: mas o rei nunca a conheceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 5, 'Então Adonias filho de Hagite se levantou, dizendo: Eu reinarei. E preparou carros e cavaleiros, e cinquenta homens que corressem adiante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 6, 'E seu pai nunca o entristeceu em todos seus dias com dizer-lhe: Por que fazes assim? E também este era de bela aparência; e havia o gerado depois de Absalão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 7, 'E tinha tratos com Joabe filho de Zeruia, e com Abiatar sacerdote, os quais ajudavam a Adonias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 8, 'Mas Zadoque sacerdote, e Benaia filho de Joiada, e Natã profeta, e Simei, e Reí, e todos os grandes de Davi, não seguiam a Adonias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 9, 'E matando Adonias ovelhas e vacas e animais engordados junto à penha de Zoelete, que está próxima da fonte de Rogel, convidou a todos seus irmãos os filhos do rei, e a todos os homens de Judá, servos do rei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 10, 'Mas não convidou a Natã profeta, nem a Benaia, nem aos grandes, nem a Salomão seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 11, 'E falou Natã a Bate-Seba mãe de Salomão, dizendo: Não ouviste que reina Adonias filho de Hagite, sem sabê-lo Davi nosso senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 12, 'Vem pois agora, e toma meu conselho, para que guardes tua vida, e a vida de teu filho Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 13, 'Vai, e entra ao rei Davi, e dize-lhe: Rei senhor meu, não juraste tu à tua serva, dizendo: Salomão teu filho reinará depois de mim, e ele se sentará em meu trono? por que pois reina Adonias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 14, 'E estando tu ainda falando com o rei, eu entrarei atrás de ti, e acabarei teus argumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 15, 'Então Bate-Seba entrou ao rei à câmara: e o rei era muito velho; e Abisague sunamita servia ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 16, 'E Bate-Seba se inclinou, e fez reverência ao rei. E o rei disse: Que tens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 17, 'E ela lhe respondeu: Senhor meu, tu juraste à tua serva pelo SENHOR teu Deus, dizendo: Salomão teu filho reinará depois de mim, e ele se sentará em meu trono;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 18, 'E eis que agora Adonias reina: e tu, meu senhor rei, agora não o soubeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 19, 'Matou bois, e animais engordados, e muitas ovelhas, e convidou a todos os filhos do rei, e a Abiatar sacerdote, e a Joabe general do exército; mas a Salomão teu servo não convidou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 20, 'Entretanto, rei senhor meu, os olhos de todo Israel estão sobre ti, para que lhes declares quem se há de sentar no trono de meu senhor o rei depois dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 21, 'De outra sorte acontecerá, quando meu senhor o rei descansar com seus pais, que eu e meu filho Salomão seremos tidos por culpados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 22, 'E estando ainda falando ela com o rei, eis que Natã profeta, que veio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 23, 'E deram aviso ao rei, dizendo: Eis que Natã profeta: o qual quando entrou ao rei, prostrou-se diante do rei inclinando seu rosto à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 24, 'E disse Natã: Rei senhor meu, disseste tu: Adonias reinará depois de mim, e ele se sentará em meu trono?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 25, 'Porque hoje desceu, e matou bois, e animais engordados, e muitas ovelhas, e convidou a todos os filhos do rei, e aos capitães do exército, e também a Abiatar sacerdote; e eis que, estão comendo e bebendo diante dele, e disseram: Viva o rei Adonias!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 26, 'Mas nem a mim teu servo, nem a Zadoque sacerdote, nem a Benaia filho de Joiada, nem a Salomão teu servo, convidou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 27, 'É este negócio ordenado por meu senhor o rei, sem haver declarado a teu servo quem se havia de sentar no trono de meu senhor o rei depois dele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 28, 'Então o rei Davi respondeu, e disse: Chamai-me a Bate-Seba. E ela entrou à presença do rei, e pôs-se diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 29, 'E o rei jurou, dizendo: Vive o SENHOR, que redimiu minha alma de toda angústia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 30, 'Que como eu te ei jurado pelo SENHOR Deus de Israel, dizendo: Teu filho Salomão reinará depois de mim, e ele se sentará em meu trono em lugar meu; que assim o farei hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 31, 'Então Bate-Seba se inclinou ao rei, seu rosto à terra, e fazendo reverência ao rei, disse: Viva meu senhor o rei Davi para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 32, 'E o rei Davi disse: Chamai-me a Zadoque sacerdote, e a Natã profeta, e a Benaia filho de Joiada. E eles entraram à presença do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 33, 'E o rei lhes disse: Tomai convosco os servos de vosso senhor, e fazei subir a Salomão meu filho em minha mula, e levai-o a Giom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 34, 'E ali o ungirão Zadoque sacerdote e Natã profeta por rei sobre Israel; e tocareis trombeta, dizendo: Viva o rei Salomão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 35, 'Depois ireis vós detrás dele, e virá e se sentará em meu trono, e ele reinará por mim; porque a ele ordenei para que seja príncipe sobre Israel e sobre Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 36, 'Então Benaia filho de Joiada respondeu ao rei, e disse: Amém. Assim o diga o SENHOR, Deus de meu senhor o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 37, 'Da maneira que o SENHOR foi com meu senhor o rei, assim seja com Salomão; e ele faça maior seu trono que o trono de meu senhor o rei Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 38, 'E desceu Zadoque sacerdote, e Natã profeta, e Benaia filho de Joiada, e os quereteus e os peleteus, e fizeram subir a Salomão na mula do rei Davi, e levaram-no a Giom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 39, 'E tomando Zadoque sacerdote o chifre do azeite do tabernáculo, ungiu a Salomão: e tocaram trombeta, e disse todo o povo: Viva o rei Salomão!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 40, 'Depois subiu todo o povo depois dele, e cantava a gente com flautas, e faziam grandes alegrias, que parecia que a terra se fendia com o barulho deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 41, 'E ouviu-o Adonias, e todos os convidados que com ele estavam, quando já haviam acabado de comer. E ouvindo Joabe o som da trombeta, disse: Por que se alvoroça a cidade com estrondo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 42, 'Estando ainda ele falando, eis que Jônatas, filho do sacerdote Abiatar, veio, ao qual Adonias disse: Entra, porque és homem digno, e trarás boas notícias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 43, 'E Jônatas respondeu, e disse a Adonias: Certamente nosso senhor, o rei Davi, constituiu rei a Salomão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 44, 'E o rei enviou com ele o sacerdote Zadoque o profeta Natã, Benaia, filho de Joiada, e também os quereteus e os peleteus, os quais lhe fizeram subir na mula do rei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 45, 'E o sacerdote Zadoque e o profeta Natã o ungiram em Giom como rei, e dali subiram alegres, e a cidade está cheia de alvoroço. Este é o barulho que ouvistes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 46, 'E também Salomão se assentou no trono do reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 47, 'E ainda os servos do rei vieram a bendizer ao nosso senhor,o rei Davi, dizendo: Deus faça o nome de Salomão melhor que o teu nome, e faça o seu trono maior que o teu. E o rei se inclinou no leito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 48, 'E também o rei falou assim: Bendito seja o SENHOR, Deus de Israel, que hoje deu quem se assente em meu trono, vendo-o meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 49, 'Então se estremeceram, e levantaram-se todos os convidados que estavam com Adonias, e foi-se cada um por seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 50, 'Mas Adonias, temendo da presença de Salomão, levantou-se e foi-se, e agarrou as pontas do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 51, 'E foi feito saber a Salomão, dizendo: Eis que que Adonias tem medo do rei Salomão: pois agarrou as pontas do altar, dizendo: Jure-me hoje o rei Salomão que não matará à espada a seu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 52, 'E Salomão disse: Se ele for virtuoso, nenhum de seus cabelos cairá em terra: mas se se achar mal nele, morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 1, 53, 'E enviou o rei Salomão, e trouxeram-no do altar; e ele veio, e inclinou-se ao rei Salomão. E Salomão lhe disse: Vai-te à tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 1, 'E achegaram-se os dias de Davi para morrer, e mandou a Salomão seu filho, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 2, 'Eu vou pelo caminho de toda a terra: esforça-te, e sê homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 3, 'Guarda a ordenança do SENHOR teu Deus, andando em seus caminhos, e observando seus estatutos e mandamentos, e seus direitos e seus testemunhos, da maneira que está escrito na lei de Moisés, para que sejas bem-sucedido em tudo o que fizeres, e em tudo aquilo a que te voltares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 4, 'Para que confirme o SENHOR a palavra que me falou, dizendo: Se teus filhos guardarem seu caminho, andando diante de mim com verdade, de todo seu coração, e de toda sua alma, jamais, disse, faltará a ti homem do trono de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 5, 'E já sabes tu o que me fez Joabe filho de Zeruia, o que fez a dois generais do exército de Israel, a Abner filho de Ner, e a Amasa filho de Jéter, os quais ele matou, derramando em paz o sangue de guerra, e pondo o sangue de guerra em seu cinto que tinha em sua cintura, e nos sapatos que tinha em seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 6, 'Tu, pois, farás conforme a tua sabedoria; não o deixarás descer ao Xeol na velhice em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 7, 'Mas aos filhos de Barzilai gileadita farás misericórdia, que sejam dos convidados a tua mesa; porque eles vieram assim a mim, quando ia fugindo de Absalão teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 8, 'Também tens contigo Simei, filho de Gera, filho de Benjamim, de Baurim, o qual me amaldiçoou com uma severa maldição no dia em que eu ia a Maanaim. Mas ele mesmo desceu para me receber junto ao Jordão, e eu lhe jurei pelo SENHOR, dizendo: Eu não te matarei à espada'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 9, 'Porém agora não o absolverás; porque és homem sábio, e sabes como agirás para com ele; e farás seus cabelos grisalhos descerem com sangue ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 10, 'E Davi descansou com seus pais, e foi sepultado na cidade de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 11, 'Os dias que reinou Davi sobre Israel foram quarenta anos: sete anos reinou em Hebrom, e trinta e três anos reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 12, 'E se sentou Salomão no trono de Davi seu pai, e foi seu reino firme em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 13, 'Então Adonias filho de Hagite veio a Bate-Seba mãe de Salomão; e ela disse: É tua vinda de paz? E ele respondeu: Sim, de paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 14, 'Em seguida disse: Uma palavra tenho que te dizer. E ela disse: Dize.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 15, 'E ele disse: Tu sabes que o reino era meu, e que todo Israel havia posto em mim seu rosto, para que eu reinasse: mas o reino foi traspassado, e veio a meu irmão; porque pelo SENHOR era seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 16, 'E agora eu te faço uma petição: não a negues a mim. E ela lhe disse: Fala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 17, 'Ele então disse: Eu te rogo que fales ao rei Salomão (porque ele não negará a ti), para que me dê a Abisague, a sunamita, por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 18, 'E Bate-Seba disse: Está bem; eu falarei por ti ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 19, 'E veio Bate-Seba ao rei Salomão para falar-lhe por Adonias. E o rei se levantou a recebê-la, e inclinou-se a ela, e voltou a sentar-se em seu trono, e fez pôr uma cadeira à mãe do rei, a qual se sentou à sua direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 20, 'E ela disse: Uma pequena petição pretendo de ti; não me negues. E o rei lhe disse: Pede, minha mãe, que eu não te negarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 21, 'E ela disse: Dê-se Abisague, a sunamita, por mulher a teu irmão Adonias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 22, 'E o rei Salomão respondeu, e disse a sua mãe: Por que pedes a Abisague sunamita para Adonias? Pede também para ele o reino, porque ele é meu irmão maior; e tem também a Abiatar sacerdote, e a Joabe filho de Zeruia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 23, 'E o rei Salomão jurou pelo SENHOR, dizendo: Assim me faça Deus e assim me acrescente, que contra sua vida falou Adonias esta palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 24, 'Agora, pois, vive o SENHOR, que me confirmou e me pôs sobre o trono de Davi meu pai, e que me fez casa, como me havia dito, que Adonias morrerá hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 25, 'Então o rei Salomão enviou por meio de Benaia filho de Joiada, o qual o golpeou de maneira que ele morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 26, 'E a Abiatar sacerdote disse o rei: Vai-te a Anatote a tuas propriedades, que tu és digno de morte; mas não te matarei hoje, porquanto levaste a arca do Senhor DEUS diante de Davi meu pai, e, além disso, foste aflito em todas as coisas em que meu pai foi aflito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 27, 'Assim expulsou Salomão a Abiatar do sacerdócio do SENHOR, para que se cumprisse a palavra do SENHOR que havia dito sobre a casa de Eli em Siló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 28, 'E veio a notícia até Joabe: porque também Joabe se havia aderido a Adonias, se bem não se havia aderido a Absalão. E fugiu Joabe ao tabernáculo do SENHOR, e agarrou-se às pontas do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 29, 'E foi feito saber a Salomão que Joabe havia fugido ao tabernáculo do SENHOR, e que estava junto ao altar. Então enviou Salomão a Benaia filho de Joiada, dizendo: Vai, e golpeia-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 30, 'E entrou Benaia ao tabernáculo do SENHOR, e disse-lhe: O rei disse que saias. E ele disse: Não, mas sim aqui morrerei. E Benaia voltou com esta resposta ao rei, dizendo: Assim falou Joabe, e assim me respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 31, 'E o rei lhe disse: Faze como ele disse; mata-lhe e enterra-o, e tira de mim e da casa de meu pai o sangue que Joabe derramou injustamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 32, 'E o SENHOR fará voltar seu sangue sobre sua cabeça; porque ele matou dois homens mais justos e melhores que ele, aos quais matou à espada sem que meu pai, Davi, soubesse nada: a Abner filho de Ner, general do exército de Israel, e a Amasa filho de Jéter, general do exército de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 33, 'O sangue deles, pois, recairá sobre a cabeça de Joabe, e sobre a cabeça de sua descendência para sempre; mas sobre Davi e sobre sua descendência, e sobre sua casa e sobre seu trono, haverá perpetuamente paz da parte do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 34, 'Então Benaia, filho de Joiada, subiu, e o golpeou, e o matou; e foi sepultado em sua casa no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 35, 'E o rei pôs em seu lugar a Benaia, filho de Joiada, sobre o exército; e o rei pôs por sacerdote a Zadoque em lugar de Abiatar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 36, 'Depois o rei mandou convocar Simei, e disse-lhe: Edifica para ti uma casa em Jerusalém, e mora ali, e não saias de lá à uma parte nem à outra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 37, 'porque sabe com certeza que no dia que saíres, e passares o ribeiro de Cedrom, sem dúvida morrerás, e teu sangue será sobre a tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 38, 'E Simei disse ao rei: A palavra é boa; como o rei, meu senhor, disse, assim teu servo o fará. E Simei morou em Jerusalém por muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 39, 'Porém passados três anos, aconteceu que se lhe fugiram a Simei dois servos a Aquis, filho de Maaca, rei de Gate. E avisaram a Simei, dizendo: Eis que teus servos estão em Gate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 40, 'Então Simei se levantou, preparou seu asno, e foi a Gate, a Aquis, para procurar seus servos. Assim Simei foi, e trouxe os seus servos de Gate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 41, 'E disseram a Salomão como Simei havia ido de Jerusalém a Gate, e que havia voltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 42, 'Então o rei mandou que convocassem a Simei, e disse-lhe: Não te fiz jurar pelo SENHOR, e te adverti, dizendo: No dia que saíres, e fores para qualquer outro lugar, sabe que com certeza morrerás? E tu me disseste: A palavra é boa, eu a obedecerei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 43, 'Por que, pois, não guardaste o juramento do SENHOR, nem o mandamento que te impus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 44, 'Disse mais o rei a Simei: Tu sabes toda a maldade, a qual teu coração conhece que cometeste contra meu pai, Davi; por isso o SENHOR retribuiu a tua maldade sobre a tua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 45, 'Mas o rei Salomão será abençoado, e o trono de Davi será confirmado diante do SENHOR para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 2, 46, 'Então o rei mandou a Benaia, filho de Joiada, o qual saiu para ferir-lhe; e ele morreu. Assim o reino foi confirmado na mão de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 1, 'E Salomão fez parentesco com Faraó, rei do Egito, porque se casou com a filha de Faraó, e a trouxe à cidade de Davi, até que acabasse de edificar a sua própria casa, e a casa do SENHOR, e os muros de Jerusalém em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 2, 'Todavia o povo sacrificava nos altares dos lugares altos, porque não havia casa edificada ao nome do SENHOR até aqueles tempos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 3, 'Mas Salomão amava ao SENHOR, andando nos estatutos de seu pai Davi, exceto que sacrificava e queimava incenso nos altares dos lugares altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 4, 'E o rei foi a Gibeão, porque aquele era o principal lugar alto, e Salomão sacrificou ali mil holocaustos sobre aquele altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 5, 'Em uma noite, o SENHOR apareceu a Salomão em sonhos. E Deus lhe disse: Pede o que [queres que] eu te dê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 6, 'E Salomão disse: Tu concedeste grande misericórdia a teu servo Davi, meu pai, como também ele andou perante ti em verdade, em justiça, e com um coração correto para contigo; e guardaste-lhe este teu grande benefício, que lhe deste um filho que se assentasse no seu trono, como acontece hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 7, 'Agora, pois, ó SENHOR meu Deus, constituíste a mim, teu servo, rei em lugar de Davi, meu pai; porém sou um tenro jovem, que não sei como entrar nem sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 8, 'E teu servo está no meio do teu povo que escolheste; um povo grande, que não se pode contar nem numerar por causa de sua multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 9, 'Dá, pois, a teu servo um coração com entendimento para julgar ao teu povo, para discernir entre o bem e o mal; pois quem poderá governar este teu tão grande povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 10, 'E foi do agrado do Senhor que Salomão pedisse isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 11, 'Deus disse-lhe: Porque pediste isto, e não pediste para ti longa vida, nem pediste para ti riquezas, nem pediste a morte de teus inimigos, mas pediste para ti entendimento para compreender a justiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 12, 'Eis que o fiz conforme as tuas palavras: eis que te dei um coração sábio e com entendimento, tanto que não houve antes de ti outro como tu, nem depois de ti se levantará outro como tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 13, 'E também te dei as coisas que não pediste: riquezas e honra; de maneira que, entre os reis, ninguém haverá semelhante a ti em todos os teus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 14, 'E se andares em meus caminhos, guardando meus estatutos e meus mandamentos, como andou Davi, teu pai, prolongarei teus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 15, 'E quando Salomão despertou, viu que era sonho: e veio a Jerusalém, e apresentou-se diante da arca do pacto do SENHOR, e sacrificou holocaustos, e fez ofertas pacíficas; fez também banquete a todos seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 16, 'Naquela muita vieram duas mulheres prostitutas ao rei, e apresentaram-se diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 17, 'E disse a uma mulher: Ah, senhor meu! Eu e esta mulher morávamos em uma mesma casa, e eu pari estando com ela na casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 18, 'E aconteceu ao terceiro dia depois que eu dei à luz, que esta deu à luz também, e morávamos nós juntas; ninguém de fora estava em casa, a não ser nós duas na casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 19, 'E uma noite o filho desta mulher morreu, porque ela se deitou sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 20, 'E levantou-se à meia noite, e tomou a meu filho de junto a mim, estando eu tua serva dormindo, e o pôs a seu lado, e pôs a meu lado seu filho morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 21, 'E quando eu me levantei pela manhã para dar o peito a meu filho, eis que que estava morto: mas observei-lhe pela manhã, e vi que não era meu filho, que eu havia dado à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 22, 'Então a outra mulher disse: Não; meu filho é o que vive, e teu filho é o morto. E a outra voltou a dizer: Não; teu filho é o morto, e meu filho é o que vive. Assim falavam diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 23, 'O rei então disse: Esta disse: Meu filho é o que vive, e teu filho é o morto: e a outra disse: Não, mas o teu é o morto, e meu filho é o que vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 24, 'E disse o rei: Trazei-me uma espada. E trouxeram ao rei uma espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 25, 'Em seguida o rei disse: Parti por meio o menino vivo, e dai a metade à uma, e a outra metade à outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 26, 'Então a mulher cujo era o filho vivo, falou ao rei (porque suas entranhas se lhe comoveram por seu filho), e disse: Ah, senhor meu! Dai a esta o menino vivo, e não o mateis. Mas a outra disse: nem a mim nem a ti; parti-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 27, 'Então o rei respondeu, e disse: Dai a aquela o filho vivo, e não o mateis: ela é sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 3, 28, 'E todo Israel ouviu aquele juízo que havia dado o rei: e temeram ao rei, porque viram que havia nele sabedoria de Deus para julgar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 1, 'Foi, pois, o rei Salomão rei sobre todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 2, 'E estes foram os príncipes que teve: Azarias filho de Zadoque, sacerdote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 3, 'Eliorefe e Aías, filhos de Sisa, escribas; Josafá filho de Ailude, chanceler;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 4, 'Benaia filho de Joiada era sobre o exército; e Zadoque e Abiatar eram os sacerdotes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 5, 'Azarias filho de Natã era sobre os governadores; Zabude filho de Natã era principal oficial, amigo do rei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 6, 'E Aisar era mordomo; e Adonirão filho de Abda era sobre o tributo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 7, 'E tinha Salomão doze governadores sobre todo Israel, os quais mantinham ao rei e à sua casa. Cada um deles estava obrigado a abastecer por um mês no ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 8, 'E estes são os nomes deles: Ben-Hur no monte de Efraim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 9, 'Ben-Dequer, em Macaz, e em Saalbim, e em Bete-Semes, e em Elom-Bete-Hanã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 10, 'Ben-Hesede, em Arubote; este tinha também a Socó e toda a terra de Hefer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 11, 'Ben-Abinadabe, em toda a região de Dor: este tinha por mulher a Tafate filha de Salomão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 12, 'Baana filho de Ailude, em Taanaque e Megido, e em toda Bete-Seã, que é próxima de Zaretã, por abaixo de Jezreel, desde Bete-Seã até Abel-Meolá, e até a outra parte de Jocmeão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 13, 'Ben-Geber, em Ramote de Gileade; este tinha também as cidades de Jair filho de Manassés, as quais estavam em Gileade; tinha também a província de Argobe, que era em Basã, sessenta grandes cidades com muro e fechaduras de bronze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 14, 'Ainadabe filho de Ido, em Maanaim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 15, 'Aimaás em Naftali; este tomou também por mulher a Basemate filha de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 16, 'Baaná filho de Husai, em Aser e em Alote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 17, 'Josafá filho de Parua, em Issacar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 18, 'Simei filho de Elá, em Benjamim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 19, 'Geber filho de Uri, na terra de Gileade, a terra de Seom rei dos amorreus, e de Ogue rei de Basã; este era o único governador naquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 20, 'Judá e Israel eram muitos, como a areia que está junto ao mar em multidão, comendo e bebendo e alegrando-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 21, 'E Salomão dominava sobre todos os reinos, desde o rio até a terra dos filisteus, e até o termo do Egito; e traziam tributos, e serviram a Salomão todos os dias em que viveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 22, 'E a provisão de Salomão era, cada dia, trinta coros de farinha refinada, e sessenta coros de farinha comum;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 23, 'dez bois engordados, e vinte bois de pasto, e cem ovelhas; sem os cervos, cabras, búfalos, e aves engordadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 24, 'Porque ele dominava em toda a região que estava da outra parte do rio, desde Tifsa até Gaza, sobre todos os reis da outra parte do rio; e teve paz por todos os lados em derredor seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 25, 'E Judá e Israel viviam seguros, cada um debaixo de sua parreira e debaixo de sua figueira, desde Dã até Berseba, todos os dias de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 26, 'Além disso, Salomão tinha quarenta mil cavalos em seus estábulos para suas carruagens, e doze mil cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 27, 'E estes governadores mantinham ao rei Salomão, e a todos os que vinham à mesa do rei Salomão, a cada mês; e faziam que nada faltasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 28, 'Faziam também trazer cevada e palha para os cavalos e para os animais de carga, ao lugar de onde ele estava, cada um conforme ao cargo que tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 29, 'E deu Deus a Salomão sabedoria, e prudência muito grande, e largura de coração como a areia que está à beira do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 30, 'Que foi maior a sabedoria de Salomão que a de todos os orientais, e que toda a sabedoria dos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 31, 'E ainda foi mais sábio que todos os homens; mais que Etã ezraíta, e que Hemã e Calcol e Darda, filhos de Maol: e foi nomeado entre todas as nações de ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 32, 'E propôs três mil parábolas; e seus versos foram mil e cinco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 33, 'Também descreveu as árvores, desde o cedro do Líbano até o hissopo que nasce na parede. Também descreveu os animais, as aves, os répteis, e os peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 4, 34, 'E vinham de todos os povos a ouvir a sabedoria de Salomão, e de todos os reis da terra, de onde havia chegado a fama de sua sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 1, 'Hirão, rei de Tiro, enviou seus servos a Salomão, quando ouviu que tinham ungido por rei em lugar de seu pai; porque Hirão sempre havia amado a Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 2, 'Então Salomão enviou a dizer a Hirão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 3, 'Tu sabes como meu pai Davi não pôde edificar uma casa ao nome do SENHOR, seu Deus, por causa das guerras que o cercaram, até que o SENHOR pôs os seus inimigos debaixo das plantas de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 4, 'Porém agora o SENHOR, meu Deus, me deu repouso por todos os lados; nem há adversários, nem encontro mal algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 5, 'Eu, portanto, decidi edificar uma casa ao nome do SENHOR, meu Deus, como o SENHOR o falou ao meu pai Davi, dizendo: Teu filho, que eu porei em teu lugar no teu trono, ele edificará uma casa ao meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 6, 'Manda, pois, agora, que me cortem cedros do Líbano; e meus servos estarão com os teus servos, e eu te darei o salário dos teus servos conforme a tudo o que disseres; porque tu sabes que ninguém há entre nós que saiba cortar a madeira como os sidônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 7, 'E quando Hirão ouviu as palavras de Salomão, alegrou-se em grande maneira, e disse: Bendito seja hoje o SENHOR, que deu filho sábio a Davi sobre este povo tão grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 8, 'E enviou Hirão a dizer a Salomão: Ouvi o que me mandaste a dizer: eu farei tudo o que te satisfizer acerca da madeira de cedro, e a madeira de faia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 9, 'Meus servos a levarão desde o Líbano à mar; e eu a porei em balsas pelo mar até o lugar que tu me assinalares, e ali se desatará, e tu a tomarás: e tu farás minha vontade em dar de comer à minha família.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 10, 'Deu, pois, Hirão a Salomão madeira de cedro e madeira de faia tudo o que quis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 11, 'E Salomão dava a Hirão vinte mil coros de trigo para o sustento de sua família, e vinte coros de azeite puro; isto dava Salomão a Hirão cada um ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 12, 'Deu, pois, o SENHOR a Salomão sabedoria como lhe havia dito: e havia paz entre Hirão e Salomão, e fizeram aliança entre ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 13, 'E o rei Salomão impôs tributo a todo Israel, e o tributo foi de trinta mil homens:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 14, 'Os quais enviava ao Líbano de dez mil em dez mil, cada mês por seu turno, vindo assim a estar um mês no Líbano, e dois meses em suas casas: e Adonirão estava sobre aquele tributo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 15, 'Tinha também Salomão setenta mil que levavam as cargas, e oitenta mil cortadores no monte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 16, 'Sem os principais oficiais de Salomão que estavam sobre a obra, três mil e trezentos, os quais tinham cargo do povo que fazia a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 17, 'E mandou o rei que trouxessem grandes pedras, pedras de grande valor, para os alicerces da casa, e pedras lavradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 5, 18, 'E os pedreiros de Salomão e os de Hirão, e os preparadores, cortaram e prepararam a madeira e pedras para lavrar a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 1, 'E foi no ano quatrocentos oitenta depois que os filhos de Israel saíram do Egito, no quarto ano do princípio do reino de Salomão sobre Israel, no mês de Zife, que é o mês segundo, que ele começou a edificar a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 2, 'A casa que o rei Salomão edificou ao SENHOR, teve sessenta côvados de comprimento e vinte de largura, e trinta côvados de altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 3, 'E o pórtico diante do templo da casa, de vinte côvados de comprimento, segundo a largura da casa, e sua largura era de dez côvados diante da casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 4, 'E fez à casa janelas largas por de dentro, e estreitas por de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 5, 'Edificou também junto ao muro da casa aposentos ao redor, contra as paredes da casa em derredor do templo e do compartimento interno: e fez câmaras ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 6, 'O aposento de abaixo era de cinco côvados de largura, e o de em meio de seis côvados de largura, e o terceiro de sete côvados de largura: porque por de fora havia feito apoios à casa em derredor, para não introduzir as vigas nas paredes da casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 7, 'E a casa quando se edificou, fabricaram-na de pedras que traziam já acabadas; de tal maneira que quando a edificavam, nem martelos nem machados se ouviram na casa, nem nenhum outro instrumento de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 8, 'A porta do aposento de em meio estava ao lado direito da casa: e subia-se por um caracol ao de em meio, e do aposento de em meio ao terceiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 9, 'Lavrou, pois, a casa, e acabou-a; e cobriu a casa com artesanatos de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 10, 'E edificou também o aposento em derredor de toda a casa, de altura de cinco côvados, o qual se apoiava na casa com madeiras de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 11, 'E veio a palavra do SENHOR a Salomão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 12, 'Esta casa que tu edificas, se andares em meus estatutos, e fizeres meus direitos, e guardares todos meus mandamentos andando neles, eu terei firme contigo minha palavra que falei a Davi teu pai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 13, 'E habitarei em meio dos filhos de Israel, e não deixarei a meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 14, 'Assim que, Salomão preparou a casa, e acabou-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 15, 'E preparou as paredes da casa por de dentro com tábuas de cedro, revestindo-a de madeira por dentro, desde o piso da casa até as paredes do teto: cobriu também o pavimento com madeira de faia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 16, 'Também fez ao fim da casa um edifício de vinte côvados de tábuas de cedro, desde o piso até o mais alto; e fabricou-se na casa um compartimento interno, que é o lugar santíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 17, 'E a casa, a saber, o templo de dentro, tinha quarenta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 18, 'E a casa estava coberta de cedro por de dentro, e tinha entalhaduras de frutos silvestres e de botões de flores. Todo era cedro; nenhuma pedra se via.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 19, 'E adornou o compartimento interno por de dentro no meio da casa, para pôr ali a arca do pacto do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 20, 'E o compartimento interno estava na parte de dentro, o qual tinha vinte côvados de comprimento, e outros vinte de largura, e outros vinte de altura; e revestiu-o de ouro puríssimo: também cobriu o altar de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 21, 'De sorte que revestiu Salomão de ouro puro a casa por de dentro, e fechou a entrada do compartimento interno com correntes de ouro, e revestiu-o de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 22, 'Cobriu, pois, de ouro toda a casa até o fim; e também revestiu de ouro todo o altar que estava diante do compartimento interno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 23, 'Fez também no compartimento interno dois querubins de madeira de oliva, cada um de altura de dez côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 24, 'A uma asa do querubim tinha cinco côvados, e a outra asa do querubim outros cinco côvados: assim que havia dez côvados desde a ponta da uma asa até a ponta da outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 25, 'Também o outro querubim tinha dez côvados; porque ambos os querubins eram de um tamanho e de uma feitura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 26, 'A altura do um era de dez côvados, e também o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 27, 'E pôs estes querubins dentro da casa de dentro: os quais querubins estendiam suas asas, de modo que a asa do um tocava à parede, e a asa do outro querubim tocava à outra parede, e as outras duas asas se tocavam a uma à outra na metade da casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 28, 'E revestiu de ouro os querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 29, 'E esculpiu todas as paredes da casa ao redor de diversas figuras, de querubins, de palmas, e de botões de flores, por de dentro e por de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 30, 'E cobriu de ouro o piso da casa, de dentro e de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 31, 'E à entrada do compartimento interno fez portas de madeira de oliva; e o umbral e os postes eram de cinco esquinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 32, 'As duas portas eram de madeira de oliva; e entalhou nelas figuras de querubins e de palmas e de botões de flores, e cobriu-as de ouro: cobriu também de ouro os querubins e as palmas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 33, 'Igualmente fez à porta do templo postes de madeira de oliva quadrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 34, 'Porém as duas portas eram de madeira de faia; e os dois lados da uma porta eram redondos, e os outros dois lados da outra porta também redondos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 35, 'E entalhou nelas querubins e palmas e botões de flores, e cobriu-as de ouro ajustado às entalhaduras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 36, 'E edificou o átrio interior de três ordens de pedras lavradas, e de uma ordem de vigas de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 37, 'No quarto ano, no mês de Zife, se lançaram os alicerces da casa do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 6, 38, 'E no décimo primeiro ano, no mês de Bul, que é o mês oitavo, foi acabada a casa com todas seus partes, e com todo o necessário. Edificou-a, pois, em sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 1, 'Depois edificou Salomão sua própria casa em treze anos, e acabou de construí-la toda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 2, 'Também edificou a casa do bosque do Líbano, a qual tinha cinco côvados de comprimento, e cinquenta côvados de largura, e trinta côvados de altura, sobre quatro ordens de colunas de cedro, com vigas de cedro sobre as colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 3, 'E estava coberta de tábuas de cedro acima sobre as vigas, que se apoiavam em quarenta e cinco colunas: cada fileira tinha quinze colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 4, 'E havia três ordens de janelas, uma janela contra a outra em três ordens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 5, 'E todas as portas e postes eram quadrados: e as umas janelas estavam de frente às outras em três ordens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 6, 'Também fez um pórtico de colunas, que tinha de comprimento cinquenta côvados, e trinta côvados de largura; e este pórtico estava diante daquelas outras, com suas colunas e vigas correspondentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 7, 'Fez também o pórtico do trono em que havia de julgar, o pórtico do juízo, e revestiu-o de cedro do chão ao teto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 8, 'E na casa em que ele morava, havia outro átrio dentro do pórtico, de obra semelhante a esta. Edificou também Salomão uma casa para a filha de Faraó, que havia tomado por mulher, da mesma obra daquele pórtico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 9, 'Todas aquelas obras foram de pedras de grande valor, cortadas e serradas com serras segundo as medidas, assim por de dentro como por de fora, desde o alicerce até os topos das paredes, e também por de fora até o grande átrio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 10, 'O alicerce era de pedras de grande valor, de pedras grandes, de pedras de dez côvados, e de pedras de oito côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 11, 'Dali acima eram também pedras de grande valor, lavradas conforme a suas medidas, e obra de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 12, 'E no grande átrio ao redor havia três ordens de pedras lavradas, e uma ordem de vigas de cedro: e assim o átrio interior da casa do SENHOR, e o átrio da casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 13, 'E enviou o rei Salomão, e fez vir de Tiro a Hirão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 14, 'Filho de uma viúva da tribo de Naftali, e seu pai havia sido de Tiro: trabalhava ele em bronze, cheio de sabedoria e de inteligência e saber em toda obra de bronze. Este pois veio ao rei Salomão, e fez toda sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 15, 'E fundiu duas colunas de bronze, a altura de cada qual era de dezoito côvados: e rodeava a uma e a outra coluna um fio de doze côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 16, 'Fez também dois capitéis de fundição de bronze, para que fossem postos sobre as cabeças das colunas: a altura de um capitel era de cinco côvados, e a do outro capitel de cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 17, 'Havia trançados à maneira de redes, e grinaldas à maneira de correntes, para os capitéis que se haviam de pôr sobre as cabeças das colunas: sete para cada capitel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 18, 'E quando havia feito as colunas, fez também duas ordens de romãs ao redor no um enredado, para cobrir os capitéis que estavam nas cabeças das colunas com as romãs: e da mesma forma fez no outro capitel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 19, 'Os capitéis que estavam sobre as colunas no pórtico, tinham trabalho de flores por quatro côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 20, 'Tinham também os capitéis de sobre as duas colunas, duzentas romãs em duas ordens ao redor em cada capitel, encima da parte arredondada do capitel, o qual estava diante do trançado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 21, 'Estas colunas ele erigiu no pórtico do templo: e quando havia levantado a coluna da direita, pôs-lhe por nome Jaquim: e levantando a coluna da esquerda, chamou seu nome Boaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 22, 'E pôs nas cabeças das colunas trabalho em forma de açucenas; e assim se acabou a obra das colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 23, 'Fez também um mar de fundição, de dez côvados do um lado ao outro, redondo; sua altura era de cinco côvados, e cingia-o ao redor um cordão de trinta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 24, 'E cercavam aquele mar por debaixo de sua borda em derredor umas bolas como frutos, dez em cada côvado, que cingiam o mar ao redor em duas ordens, as quais haviam sido fundidas quando ele foi fundido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 25, 'E estava assentado sobre doze bois: três estavam voltados ao norte, e três estavam voltados ao ocidente, e três estavam voltados ao sul, e três estavam voltados ao oriente; sobre estes se apoiava o mar, e as traseiras deles estavam até a parte de dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 26, 'A espessura do mar era de um palmo, e sua borda era lavrada como a borda de um cálice, ou de flor de lírio: e cabiam nele dois mil batos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 27, 'Fez também dez bases de bronze, sendo o comprimento de cada base de quatro côvados, e a largura de quatro côvados, e de três côvados a altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 28, 'A obra das bases era esta: tinham uns painéis, as quais estavam entre molduras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 29, 'E sobre aqueles painéis que estavam entre as molduras, figuras de leões, e de bois, e de querubins; e sobre as molduras da base, assim encima como debaixo dos leões e dos bois, havia uns acréscimos de baixo-relevo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 30, 'Cada base tinha quatro rodas de bronze com mesas de bronze; e em seus quatro eixos havia uns apoios, os quais haviam sido fundidos a cada lado com grinaldas, para estarem debaixo da fonte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 31, 'E a abertura da bacia era de um côvado no suporte que saía para acima da base; e era sua abertura redonda, da feitura do mesmo suporte, e este de côvado e meio. Havia também sobre a abertura entalhes em seus painéis, que eram quadrados, não redondas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 32, 'As quatro rodas estavam debaixo dos painéis, e os eixos das rodas estavam na mesma base. A altura de cada roda era de um côvado e meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 33, 'E a feitura das rodas era como a feitura das rodas de um carro: seus eixos, seus raios, e seus cubos, e seus aros, tudo era de fundição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 34, 'Também os quatro apoios às quatro esquinas de cada base: e os apoios eram da mesma base.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 35, 'E no alto da base havia meio côvado de altura redondo por todas partes: e encima da base suas molduras e painéis, as quais eram dela mesma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 36, 'E fez nas tábuas das molduras, e nas cintas, entalhaduras de querubins, e de leões, e de palmas, com proporção no espaço de cada uma, e ao redor outros adornos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 37, 'De esta forma fez dez bases fundidas de uma mesma maneira, de uma mesma medida, e de uma mesma entalhadura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 38, 'Fez também dez fontes de bronze: cada fonte continha quarenta batos, e cada uma era de quatro côvados; e assentou uma fonte sobre cada uma das dez bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 39, 'E pôs as cinco bases à direita da casa, e as outras cinco à esquerda: e assentou o mar ao lado direito da casa, ao oriente, até o sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 40, 'Também fez Hirão fontes, e tenazes, e bacias. Assim acabou toda a obra que fez a Salomão para a casa do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 41, 'A saber, duas colunas, e os vasos redondos dos capitéis que estavam no alto das duas colunas; e duas redes que cobriam os dois vasos redondos dos capitéis que estavam sobre a cabeça das colunas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 42, 'E quatrocentas romãs para as duas redes, duas ordens de romãs em cada rede, para cobrir os dois vasos redondos que estavam sobre as cabeças das colunas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 43, 'E as dez bases, e as dez fontes sobre as bases;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 44, 'E um mar, e doze bois debaixo do mar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 45, 'E caldeiras, e pás, e bacias; e todos os vasos que Hirão fez ao rei Salomão, para a casa do SENHOR de bronze polido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 46, 'Todo o fez fundir o rei na planície do Jordão, em terra argilosa, entre Sucote e Zaretã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 47, 'E deixou Salomão sem inquirir o peso do bronze de todos os vasos, pela grande abundância deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 48, 'Então fez Salomão todos os vasos que pertenciam à casa do SENHOR: um altar de ouro, e uma mesa sobre a qual estavam os pães da proposição, também de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 49, 'E cinco candelabros de ouro puríssimo à direita, e outros cinco à esquerda, diante do oráculo; com as flores, e as lâmpadas, e tenazes de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 50, 'Também os cântaros, vasos, bacias, colheres, e incensários, de ouro puríssimo; também de ouro as dobradiças das portas da casa de dentro, do lugar santíssimo, e os das portas do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 7, 51, 'Assim se acabou toda a obra que dispôs fazer o rei Salomão para a casa do SENHOR. E meteu Salomão o que Davi seu pai havia dedicado, é a saber, prata, e ouro, e vasos, e o pôs tudo em guarda nas tesourarias da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 1, 'Então juntou Salomão os anciãos de Israel, e a todos os chefes das tribos, e aos príncipes das famílias dos filhos de Israel, ao rei Salomão em Jerusalém para trazer a arca do pacto do SENHOR da cidade de Davi, que é Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 2, 'E se juntaram ao rei Salomão todos os homens de Israel no mês de Etanim, que é o mês sétimo, no dia solene.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 3, 'E vieram todos os anciãos de Israel, e os sacerdotes tomaram a arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 4, 'E levaram a arca do SENHOR, e o tabernáculo do testemunho, e todos os vasos sagrados que estavam no tabernáculo; os quais levavam os sacerdotes e levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 5, 'E o rei Salomão, e toda a congregação de Israel que a ele se havia juntado, estavam com ele diante da arca, sacrificando ovelhas e bois, que pela abundância não se podiam contar nem numerar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 6, 'E os sacerdotes puseram a arca do pacto do SENHOR em seu lugar, no oráculo da casa, no lugar santíssimo, debaixo das asas dos querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 7, 'Porque os querubins tinham estendidas as asas sobre o lugar da arca, e assim cobriam os querubins a arca e suas varas por encima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 8, 'E fizeram sair as varas, de maneira que as extremidades das varas podiam ser vistas desde o santuário diante do compartimento interno, mas não se viam desde fora: e assim ficaram até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 9, 'Na arca nenhuma coisa havia mais das duas tábuas de pedra que havia ali posto Moisés em Horebe, de onde o SENHOR fez a aliança com os filhos de Israel, quando saíram da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 10, 'E quando os sacerdotes saíram do santuário, a nuvem encheu a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 11, 'E os sacerdotes não puderam estar para ministrar por causa da nuvem; porque a glória do SENHOR havia enchido a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 12, 'Então disse Salomão: o SENHOR disse que ele habitaria na escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 13, 'Eu edifiquei casa por morada para ti, assento em que tu habites para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 14, 'E virando o rei seu rosto, abençoou a toda a congregação de Israel; e toda a congregação de Israel estava em pé.')
